function conflictBar(){const c=state.conflict,bar=$('#git-ux-conflict-bar');if(!bar)return;if(!c){bar.hidden=true;bar.innerHTML='';$$('.repobar [data-op="REMOTE-PULL"],.repobar [data-op="REMOTE-PUSH"]').forEach(el=>{el.disabled=false;el.title='' });return}bar.hidden=false;bar.className='conflictbar '+c.phase;const left=c.files.filter(f=>f.phase!=='resolved').length;bar.innerHTML=`<span class="conflictlabel ${c.phase}">${esc(c.kind)} · ${esc(phaseLabel[c.phase])}</span><span>${c.active?`${left} 個未解決檔案 · ${state.unresolved} 個待儲存區塊`:'已離開衝突處理狀態'}</span><small>${esc(c.source)} → ${esc(c.target)}</small><span class="spacer"></span>${c.active?btn('CONFLICT-LIST','查看衝突狀態'):btn('CONFLICT-LIST','查看處理結果')}`;
 const badge=$('#conflictBadge');if(badge)badge.textContent=c.active?left:0;
 if(c.active)$('#git-ux-status').textContent=`${c.kind} 進行中 · ${phaseLabel[c.phase]} · ${left} 個未解決檔案 · 快照 v${state.version}`;
 for(const id of ['REMOTE-PULL','REMOTE-PUSH']){$$('.repobar [data-op="'+id+'"]').forEach(el=>{el.disabled=c.active;el.title=c.active?'請先完成或中止目前操作':''})}
}
