 if(syncEl)syncEl.textContent=`↑${state.ahead} ↓${state.behind}`;
 const pathEl=$('#git-ux-path');if(pathEl)pathEl.textContent=state.repoPath||'D:/Projects/EluSlot';
 if(statusEl)statusEl.textContent=`${state.scenario} · 快照 v${state.version} · ${state.files.filter(f=>f.staged).length} 已暫存 / ${state.files.filter(f=>f.dirty).length} 未暫存`;
 railEl.innerHTML='<div class="caption">PROJECT / GIT</div>'+Object.entries(views).map(([v,label])=>`<button type="button" data-view="${v}" data-op="${listIds[v]}" class="${state.view===v?'activebtn':''}">${label}${v==='changes'?` <span class="count">${state.files.length}</span>`:v==='conflicts'?` <span id="conflictBadge" class="count">${state.conflict?.active?state.conflict.files.filter(f=>f.phase!=='resolved').length:0}</span>`:''}</button>`).join('');
